	 * ```ts
	 * it('my workflow test', async () => {
	 *   await using instance = await introspectWorkflowInstance(env.WORKFLOW, "123456");
	 *
	 *   // ... your test logic ...
	 *
	 *   // .dispose() is automatically called here at the end of the scope
	 * });
	 * ```
	 */
	[Symbol.asyncDispose](): Promise<void>;
}

