1	/**
2	 * SSR'd /oauth/authorize handler. Renders a minimal IdP chooser that
3	 * lets an MCP-client-initiated OAuth flow finish via the same IdP
4	 * legs as a SPA sign-in. The parsed OAuth authorize request is
5	 * stashed in OAUTH_KV under a short-lived `authReq:<id>` key; the
6	 * IdP `start` URLs receive `?oauth_request_id=<id>` so the callback
7	 * can resume + call `provider.completeAuthorization`.
8	 *
9	 * The page is intentionally dependency-free HTML — no SPA boot — so
10	 * the IdP chooser renders instantly and works even if the client
11	 * blocks the Workers Assets bundle.
12	 */
13	
14	import type { Env } from '../env'
15	import { randomToken } from '../util/base64url'
16	import { accessTrustConfigured, verifyCfAccessJwt } from '../auth/cf-access'
17	import { EmailOnOtherIdpError, upsertUser } from '../db/queries/users'
18	import { completeMcpAuthorization } from '../idp/complete-mcp'
19	
20	const AUTH_REQ_TTL_SECONDS = 600
21	
22	export async function handleAuthorize(request: Request, env: Env): Promise<Response> {
23	  const authReq = await env.OAUTH_PROVIDER.parseAuthRequest(request)
24	  const requestId = randomToken(24)
25	  await env.OAUTH_KV.put(`authReq:${requestId}`, JSON.stringify(authReq), {
26	    expirationTtl: AUTH_REQ_TTL_SECONDS
27	  })
28	
29	  // Cloudflare Access bridge. When this path is gated by Access (e.g. the mcp.*
30	  // custom domain), the edge has already authenticated the user against the org
31	  // IdP and forwards a signed `Cf-Access-Jwt-Assertion`. Trust it to complete
32	  // the MCP grant directly — skipping the GitHub/Google chooser, which Entra-only
33	  // users can't satisfy. Mirrors `establishFromAccess` in auth/middleware.ts (the
34	  // SPA path); the only difference is the tail completes an OAuth grant instead
35	  // of minting a session cookie. Falls through to the chooser when there's no /
36	  // an invalid Access token, so the app stays generic for non-Access deploys.
37	  if (accessTrustConfigured(env)) {
38	    const viaAccess = await tryCompleteViaAccess(request, env, requestId)
39	    if (viaAccess) return viaAccess
40	  }
41	
42	  const idps = enabledIdps(env)
43	  const clientName = await tryClientName(env, authReq.clientId)
44	  return new Response(renderPage(requestId, idps, clientName), {
45	    status: 200,
46	    headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store' }
47	  })
48	}
49	
50	/** Look up the authorize request that was stashed for this requestId. */
51	export async function consumeAuthRequest(env: Env, requestId: string): Promise<unknown | null> {
52	  const raw = await env.OAUTH_KV.get(`authReq:${requestId}`)
53	  if (!raw) return null
54	  // Delete after the lookup so the request is single-use; ignore errors
55	  // (KV will TTL it anyway).
56	  env.OAUTH_KV.delete(`authReq:${requestId}`).catch(() => {})
57	  try {
58	    return JSON.parse(raw)
59	  } catch {
60	    return null
61	  }
62	}
63	
64	/**
65	 * Complete the MCP authorize grant from a Cloudflare Access token, or return
66	 * null to fall back to the IdP chooser.
67	 *
68	 * Returns a Response in two terminal cases: the grant completed (302 to the
69	 * client, from `completeMcpAuthorization`), or a 403 page for a stored
70	 * suspended/pending account. Returns null only when there is no usable Access
71	 * token (header absent or verification failed) so the caller renders the
72	 * chooser — keeping the handler generic for non-Access deployments.
73	 *
74	 * Admission mirrors `establishFromAccess` (auth/middleware.ts): Access has
75	 * already decided WHO may reach this path, so we skip the local IdP allowlist —
76	 * but the stored lifecycle status still wins (an in-app suspend blocks) and
77	 * ADMIN_EMAILS still confers admin via `upsertUser`. `requestId` is the id under
78	 * which the parsed authorize request was just stashed in OAUTH_KV;
79	 * `completeMcpAuthorization` consumes it.
80	 */
81	async function tryCompleteViaAccess(
82	  request: Request,
83	  env: Env,
84	  requestId: string
85	): Promise<Response | null> {
86	  const token = request.headers.get('cf-access-jwt-assertion')
87	  if (!token) return null
88	  const identity = await verifyCfAccessJwt(token, env)
89	  if (!identity) return null
90	
91	  let user: Awaited<ReturnType<typeof upsertUser>>['user']
92	  try {
93	    ;({ user } = await upsertUser(
94	      env,
95	      {
96	        idp: 'access',
97	        idpSub: identity.sub,
98	        email: identity.email,
99	        name: identity.name,
100	        avatarUrl: null
101	      },
102	      'active'
103	    ))
104	  } catch (err) {
105	    if (err instanceof EmailOnOtherIdpError) {
106	      console.warn('[access] email belongs to a user on another idp; refusing MCP grant')
107	      return renderBlockedPage('email_other_idp')
108	    }
109	    throw err
110	  }
111	  if (user.status !== 'active') return renderBlockedPage(user.status)
112	
113	  return completeMcpAuthorization(env, requestId, user)
114	}
