import { z } from 'zod'
import { FolderPath } from './docs-types'
import { VisibilityRulePayload } from './upstream-api'
import { prefixedSlug } from './slug'
import { isHttpsOrLoopback } from './url-trust'

// ----- enums -------------------------------------------------------------

export const GitProvider = z.enum(['github', 'gitlab', 'azure'])
export type GitProvider = z.infer<typeof GitProvider>

export const GitCredStrategy = z.enum(['shared_bearer', 'user_bearer', 'user_oauth'])
export type GitCredStrategy = z.infer<typeof GitCredStrategy>

export const GitSyncInterval = z.enum(['hourly', '6x_daily', '2x_daily', 'daily', 'weekly'])
export type GitSyncInterval = z.infer<typeof GitSyncInterval>

export const GitSyncStatus = z.enum(['ok', 'partial', 'error'])
export type GitSyncStatus = z.infer<typeof GitSyncStatus>

export const GitSyncState = z.enum(['clean', 'local_edits', 'pr_open', 'conflict'])
export type GitSyncState = z.infer<typeof GitSyncState>

export const GitPrState = z.enum(['open', 'merged', 'closed', 'error'])
export type GitPrState = z.infer<typeof GitPrState>

// ----- field shapes ------------------------------------------------------

export const GitSourceSlug = z
  .string()
  .min(1)
  .max(96)
  .regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/, 'lowercase, digits and dashes only')

// Folder root: '' (repo mirrored at the doc-store root) or a FolderPath.
export const GitFolderRoot = z.union([z.literal(''), FolderPath])

// Base URL trust boundary — same rules as UpstreamUrl, shared via
// `url-trust.ts`: https only (http allowed only for loopback in dev). The
// self-loop guard (never ctxlayer's own host) is enforced server-side in
// the admin handler via `isSameOrigin`, since it needs `PUBLIC_BASE_URL`.
export const GitBaseUrl = z
  .url()
  .refine(isHttpsOrLoopback, 'must be https (http allowed only for localhost)')

// ----- admin row + requests ----------------------------------------------

// Non-secret view of a source's static-OAuth client config (for form prefill).
export const GitOAuthPublic = z.object({
  clientId: z.string(),
  authorizeUrl: z.string(),
  tokenUrl: z.string(),
  scopes: z.array(z.string())
})
export type GitOAuthPublic = z.infer<typeof GitOAuthPublic>

export const AdminGitSourceRow = z.object({
  id: z.string(),
  slug: GitSourceSlug,
  displayName: z.string(),
  // The connection this repo's auth hangs under (add a sibling repo by reusing it).
  connectionId: z.string(),
  provider: GitProvider,
  baseUrl: z.string().nullable(),
  owner: z.string(),
  project: z.string(),
  repo: z.string(),
  branch: z.string(),
  pathPrefix: z.string(),
  // Product this source belongs to; synced docs are auto-tagged with it.
  productId: z.string().nullable(),
  readStrategy: GitCredStrategy,
  writeStrategy: GitCredStrategy,
  folderRoot: z.string(),
  syncInterval: GitSyncInterval,
  enabled: z.boolean(),
  visibility: z.array(VisibilityRulePayload),
  lastSyncedAt: z.number().int().nullable(),
  lastSyncStatus: GitSyncStatus.nullable(),
  lastSyncError: z.string().nullable(),
  docCount: z.number().int().min(0),
  sharedCredentialConfigured: z.boolean(),
  // The source's static-OAuth client config (NON-secret fields only) for the
  // admin form to prefill, or null when OAuth isn't configured.
  oauth: GitOAuthPublic.nullable().default(null),
  // True iff an OAuth client secret is sealed on this source. The secret
  // itself is never returned; this drives the "secret set" placeholder.
  clientSecretConfigured: z.boolean().default(false),
  currentUserConnected: z.boolean(),
  createdAt: z.number().int(),
  updatedAt: z.number().int()
})
export type AdminGitSourceRow = z.infer<typeof AdminGitSourceRow>

export const CreateGitSourceRequest = z.object({
  // `repo-` prefix enforced on new sources. The base `GitSourceSlug`
  // (used by AdminGitSourceRow) stays permissive so existing sources read.
  slug: prefixedSlug('gitSource'),
  displayName: z.string().min(1).max(120),
  provider: GitProvider,
  baseUrl: GitBaseUrl.optional(),
  // Attach to an existing connection (share its auth) instead of making a new
  // one. Provider must match the connection's; baseUrl is inherited from it.
  connectionId: z.string().optional(),
  owner: z.string().max(200).optional(),
  project: z.string().max(200).optional(),
  repo: z.string().min(1).max(200),
  // Blank/omitted ⇒ auto-detect the repo's default branch on first sync.
  branch: z.string().max(200).optional(),
  pathPrefix: z.string().max(200).optional(),
  productId: z.string().nullable().optional(),
  readStrategy: GitCredStrategy.optional(),
  writeStrategy: GitCredStrategy.optional(),
  folderRoot: GitFolderRoot.optional(),
  syncInterval: GitSyncInterval.optional(),
  enabled: z.boolean().optional()
})
export type CreateGitSourceRequest = z.infer<typeof CreateGitSourceRequest>

export const UpdateGitSourceRequest = z.object({
  displayName: z.string().min(1).max(120).optional(),
  baseUrl: GitBaseUrl.nullable().optional(),
  owner: z.string().max(200).optional(),
  project: z.string().max(200).optional(),
  repo: z.string().min(1).max(200).optional(),
  // Blank ⇒ reset to auto-detect the repo's default branch on next sync.
  branch: z.string().max(200).optional(),
  pathPrefix: z.string().max(200).optional(),
  productId: z.string().nullable().optional(),
  readStrategy: GitCredStrategy.optional(),
  writeStrategy: GitCredStrategy.optional(),
  folderRoot: GitFolderRoot.optional(),
  syncInterval: GitSyncInterval.optional(),
  enabled: z.boolean().optional()
})
export type UpdateGitSourceRequest = z.infer<typeof UpdateGitSourceRequest>

// PAT for the org-level shared (read) credential, or a per-user token.
export const GitSetCredentialRequest = z.object({
  token: z.string().min(1).max(4096)
})
export type GitSetCredentialRequest = z.infer<typeof GitSetCredentialRequest>

// Admin: configure a source's static (pre-registered) OAuth client. DCR is not
// used (see J-git.md), so the operator supplies the app's endpoints + id, and
// optionally the secret (sealed server-side; never round-tripped on read).
const HttpsUrl = z
  .url()
  .refine((v) => v.startsWith('https://'), { error: 'must be https' })

export const GitOAuthConfigRequest = z.object({
  clientId: z.string().min(1).max(512),
  authorizeUrl: HttpsUrl,
  tokenUrl: HttpsUrl,
  scopes: z.array(z.string().max(200)).max(50).default([]),
  // Write-only. Omit on edit to keep the existing sealed secret.
  clientSecret: z.string().min(1).max(4096).optional()
})
export type GitOAuthConfigRequest = z.infer<typeof GitOAuthConfigRequest>

// POST /api/admin/git-sources/:id/sync result.
export const GitSyncResult = z.object({
  status: GitSyncStatus,
  created: z.number().int().min(0),
  updated: z.number().int().min(0),
  deleted: z.number().int().min(0),
  skipped: z.number().int().min(0),
  conflicts: z.number().int().min(0),
  error: z.string().nullable()
})
export type GitSyncResult = z.infer<typeof GitSyncResult>

// ----- per-doc git status (editor panel) ---------------------------------

export const GitPrRef = z.object({
  url: z.string(),
  providerPrId: z.string(),
  state: GitPrState
})
export type GitPrRef = z.infer<typeof GitPrRef>

export const GitDocStatus = z.object({
  gitSourceId: z.string(),
  sourceSlug: z.string(),
  provider: GitProvider,
  branch: z.string(),
  path: z.string(),
  webUrl: z.string(),
  syncState: GitSyncState.nullable(),
  syncedAt: z.number().int().nullable(),
  canWrite: z.boolean(),
  // The connection's write strategy + whether THIS user has connected their
  // own token. Together they drive the rail's "smart connect": a per-user
  // strategy (user_oauth/user_bearer) with currentUserConnected=false is the
  // only case that should surface Connect; shared-token sources never do.
  writeStrategy: GitCredStrategy.default('user_bearer'),
  currentUserConnected: z.boolean().default(false),
  // True iff the connection has static-OAuth configured — Connect-via-OAuth
  // vs the paste-a-PAT field.
  oauthConfigured: z.boolean().default(false),
  // True iff source.md carries HTML the BlockNote round-trip can't preserve
  // (comments, anchors, <details>, styling tags). The editor disables
  // write-back for these — editing would silently drop that HTML — so the user
  // is steered to edit in git directly.
  htmlRoundtripUnsafe: z.boolean().default(false),
  pr: GitPrRef.nullable()
})
export type GitDocStatus = z.infer<typeof GitDocStatus>

// POST /api/docs/:id/git/pull-request — markdown produced client-side by
// the editor (blocksToMarkdownLossy). Capped to match the content route.
export const CreatePullRequestRequest = z.object({
  markdown: z.string().max(2 * 1024 * 1024)
})
export type CreatePullRequestRequest = z.infer<typeof CreatePullRequestRequest>

export const CreatePullRequestResult = z.object({
  // 'noop' when the normalized markdown equals the synced baseline.
  outcome: z.enum(['opened', 'updated', 'noop']),
  pr: GitPrRef.nullable()
})
export type CreatePullRequestResult = z.infer<typeof CreatePullRequestResult>

// POST /api/docs/:id/git/review-url — commit the branch, then return the
// provider's New-PR deep-link for the user to review + open in the provider
// UI. `redirectUrl` is null only on a no-op with no existing PR (nothing to
// open). `branch` is the head branch the change was pushed to.
export const GitReviewUrlResult = z.object({
  redirectUrl: z.string().nullable(),
  branch: z.string().nullable()
})
export type GitReviewUrlResult = z.infer<typeof GitReviewUrlResult>

/**
 * Inbound git sync: mirror *.md from a source's pinned branch into the
 * doc store, then enqueue reindex.
 *
 * Idempotent + change-aware: a doc whose stored blob sha matches the
 * tree entry is skipped (no fetch, no reindex). Docs with unmerged local
 * work (local_edits / pr_open) are marked `conflict` rather than
 * clobbered. Vanished blobs soft-delete their (clean) docs.
 *
 * Git-synced docs store raw markdown as the canonical body
 * (docs/{docId}/source.md); the reindex consumer chunks it directly and
 * the editor materialises BlockNote blocks lazily on first open.
 */

import type { Env } from '../env'
import type { GitSyncInterval, GitSyncResult } from '@ctxlayer/shared'
import { DOC_LIMITS, clampText, parseFrontmatter, slugifyHeading } from '@ctxlayer/shared'
import { applyOkfMetadata } from '../docs/okf-import'
import {
  getGitSourceById,
  listGitDocPaths,
  markDocGitOrigin,
  patchGitSource,
  recordSyncResult,
  setDocGitSyncState,
  type GitSourceRow
} from '../db/queries/git-sources'
import { createDoc, softDeleteDoc } from '../db/queries/docs'
import { setDocProductTag } from '../db/queries/doc-tags'
import { writeSourceMarkdown } from '../storage/docs-r2'
import { createGitProvider } from './provider'
import type { GitRepoConfig } from './provider-types'
import { resolveGitReadToken } from './credentials'
import { errMessage } from '../util/errors'

export interface RunGitSyncOpts {
  /** Acting user, for user_* read strategies (interactive sync). */
  userId?: string
}

// Minimum elapsed seconds between scheduled syncs per cadence. The
// hourly cron enqueues a source only once its interval has elapsed.
const SYNC_GAP_SECONDS: Record<GitSyncInterval, number> = {
  hourly: 3600,
  '6x_daily': 4 * 3600,
  '2x_daily': 12 * 3600,
  daily: 24 * 3600,
  weekly: 7 * 24 * 3600
}

/**
 * Whether a source is due for a scheduled sync. A 5-minute slack absorbs
 * cron jitter so a source that synced 59½ minutes ago isn't skipped on
 * the next hourly tick. Never-synced sources are always due.
 */
export function isGitSyncDue(
  interval: GitSyncInterval,
  lastSyncedAt: number | null,
  nowSec: number
): boolean {
  if (lastSyncedAt == null) return true
  const gap = SYNC_GAP_SECONDS[interval] ?? SYNC_GAP_SECONDS.daily
  return nowSec - lastSyncedAt >= gap - 300
}

const ZERO = { created: 0, updated: 0, deleted: 0, skipped: 0, conflicts: 0 }

/** A provider "branch not found" signal — `<provider>_ref_unresolved`. */
function isRefUnresolved(err: unknown): boolean {
  return err instanceof Error && /_ref_unresolved$/.test(err.message)
}

export async function runGitSync(
  env: Env,
  sourceId: string,
  opts: RunGitSyncOpts = {}
): Promise<GitSyncResult> {
  const source = await getGitSourceById(env, sourceId)
  if (!source) return { status: 'error', ...ZERO, error: 'source_not_found' }
  if (source.enabled !== 1) return { status: 'error', ...ZERO, error: 'source_disabled' }

  const token = await resolveGitReadToken(env, source, { userId: opts.userId })
  if (!token) {
    await recordSyncResult(env, sourceId, 'error', 'no_read_token')
    return { status: 'error', ...ZERO, error: 'no_read_token' }
  }

  const provider = createGitProvider(repoConfig(source), token)
  const counts = { ...ZERO }

  try {
    // Blank branch ⇒ auto-detect the repo's default and persist it (so the
    // drawer reflects it + future syncs are stable). Avoids the old silent
    // 'main' default that broke ADO repos defaulting to 'master'.
    let branch = source.branch.trim()
    if (!branch) {
      const def = await provider.getDefaultBranch()
      if (!def) throw new Error('repo_no_default_branch')
      branch = def
      await patchGitSource(env, sourceId, { branch })
    }

    // A configured-but-missing branch becomes a friendly, default-naming
    // error (branch_not_found:<typed>:<default>) instead of the opaque
    // <provider>_ref_unresolved.
    let headSha: string
    try {
      headSha = await provider.resolveRef(branch)
    } catch (err) {
      if (isRefUnresolved(err)) {
        const def = await provider.getDefaultBranch().catch(() => null)
        throw new Error(`branch_not_found:${branch}:${def ?? ''}`)
      }
      throw err
    }

    const entries = await provider.listMarkdownTree(branch, source.path_prefix)
    const existing = await listGitDocPaths(env, sourceId)
    // One read up front instead of a per-path lookup per tree entry —
    // a no-op sync over a large repo used to cost one D1 round trip
    // per markdown file.
    const docByPath = new Map(existing.map((e) => [e.git_path, e]))
    const seen = new Set<string>()

    for (const entry of entries) {
      seen.add(entry.path)
      const doc = docByPath.get(entry.path) ?? null

      if (doc && doc.git_blob_sha === entry.blobSha) {
        counts.skipped++
        continue
      }
      if (doc && (doc.git_sync_state === 'local_edits' || doc.git_sync_state === 'pr_open')) {
        // Remote moved while we hold unmerged local work — flag, don't clobber.
        await setDocGitSyncState(env, doc.id, 'conflict')
        counts.conflicts++
        continue
      }

      const file = await provider.readFile(entry.path, branch)
      // Parse OKF frontmatter once: title falls back to the body's H1, the
      // well-known fields land on the doc, the rest is preserved verbatim.
      const fm = parseFrontmatter(file.text)
      let docId: string
      if (doc) {
        docId = doc.id
      } else {
        const created = await createDoc(env, {
          title: clampText(
            fm.known.title?.trim() || deriveTitle(fm.body, entry.path),
            DOC_LIMITS.title
          ),
          folder: repoPathToFolder(source.folder_root, entry.path),
          createdBy: source.created_by
        })
        docId = created.id
      }
      // source.md stays the EXACT repo file (incl. frontmatter) — it's the
      // write-back diff baseline. The reindex consumer strips frontmatter
      // before chunking; OKF fields are projected onto the doc separately.
      await writeSourceMarkdown(env, docId, file.text)
      await markDocGitOrigin(env, docId, {
        sourceId,
        path: entry.path,
        blobSha: entry.blobSha,
        commitSha: headSha
      })
      await applyOkfMetadata(env, docId, fm.known, fm.raw)
      // Auto-tag with the source's product (drives search_docs scope).
      // Set BEFORE the reindex enqueue so the consumer's tag read picks
      // it up. null clears any product tag (source has no product).
      await setDocProductTag(env, docId, source.product_id)
      // Reindex from source.md directly (revisionId = the commit we read at).
      await env.DOC_REINDEX_QUEUE.send({ docId, revisionId: headSha, source: 'git' })
      if (doc) counts.updated++
      else counts.created++
    }

    // Deletions: a doc whose path no longer appears in the tree. Only
    // drop clean docs — anything with local edits / an open PR is left
    // for the operator to resolve.
    for (const e of existing) {
      if (seen.has(e.git_path)) continue
      if (e.git_sync_state === null || e.git_sync_state === 'clean') {
        await softDeleteDoc(env, e.id)
        counts.deleted++
      }
    }

    const status: GitSyncResult['status'] = counts.conflicts > 0 ? 'partial' : 'ok'
    await recordSyncResult(env, sourceId, status, null)
    return { status, ...counts, error: null }
  } catch (err) {
    const msg = errMessage(err)
    await recordSyncResult(env, sourceId, 'error', msg)
    return { status: 'error', ...counts, error: msg }
  }
}

function repoConfig(s: GitSourceRow): GitRepoConfig {
  return {
    provider: s.provider,
    baseUrl: s.base_url,
    owner: s.owner,
    project: s.project,
    repo: s.repo
  }
}

/** Title from the first H1, else the filename sans markdown extension. */
function deriveTitle(markdown: string, path: string): string {
  const h1 = markdown.match(/^#\s+(.+)$/m)?.[1]?.trim()
  if (h1) return h1.slice(0, 200)
  const base = path.split('/').pop() ?? path
  return base.replace(/\.(md|mdown|markdown|mkd)$/i, '') || path
}

/**
 * Map a repo file path to a ctxlayer folder under `folderRoot`. Segments
 * are slugified (non-slug repo dirs become slug-shaped) and capped at
 * depth 5 to satisfy FolderPath. The true repo path is preserved on the
 * doc's git_path regardless; this is only for browse grouping.
 */
function repoPathToFolder(folderRoot: string, repoPath: string): string | null {
  const dir = repoPath.includes('/') ? repoPath.slice(0, repoPath.lastIndexOf('/')) : ''
  const rootSegs = folderRoot
    .replace(/^\/+|\/+$/g, '')
    .split('/')
    .filter(Boolean)
  const dirSegs = dir.split('/').filter(Boolean)
  const segs = [...rootSegs, ...dirSegs].map(slugifyHeading).filter(Boolean).slice(0, 5)
  return segs.length === 0 ? null : `/${segs.join('/')}`
}

