/**
 * R2 layout for doc bodies. Two object kinds per doc:
 *
 *   docs/{docId}/snapshot.json            -- always reflects current_rev
 *   docs/{docId}/revisions/{revId}.json   -- immutable per-save copies
 *
 * Snapshot is a convenience: the MCP `get_doc` tool (M2c) and SPA
 * editor load fetch the snapshot in one round-trip without first
 * reading `documents.current_rev_id` from D1. Snapshot and the latest
 * revision row are equal by content_hash; if they ever diverge (e.g.
 * crashed mid-write), the revision row wins on the next read.
 *
 * Bodies are BlockNote JSON (see PLAN.md M2a decision). The shared
 * snapshot/revision machinery lives in revision-store.ts; this module
 * instantiates it under the `docs/` prefix and adds the doc-only
 * extras (source markdown for git-synced docs, Yjs binary snapshots).
 */

import type { Env } from '../env'
import { sha256Hex } from '../crypto/hash'
import { makeRevisionStore } from './revision-store'

export type { PutResult } from './revision-store'

const YJS_CONTENT_TYPE = 'application/octet-stream'
const MARKDOWN_CONTENT_TYPE = 'text/markdown; charset=utf-8'

const store = makeRevisionStore('docs')

export const writeRevisionAndSnapshot = store.writeRevisionAndSnapshot
export const readSnapshot = store.readSnapshot
export const readSnapshotHash = store.readSnapshotHash
export const hashContent = store.hashContent
export const contentDigest = store.contentDigest
export const writeMaterializedSnapshot = store.writeMaterializedSnapshot
export const deleteRevisionObjects = store.deleteRevisionObjects
export const readRevision = store.readRevision
export const restoreFromRevision = store.restoreFromRevision

/**
 * Canonical raw markdown for git-synced docs. Source of truth for these
 * docs (the BlockNote blocks snapshot is derived, materialised lazily in
 * the browser on first open). The reindex consumer chunks this directly
 * for RAG, skipping the lossy blocks→markdown render.
 */
function sourceMarkdownKey(docId: string): string {
  return `docs/${docId}/source.md`
}

export async function writeSourceMarkdown(
  env: Env,
  docId: string,
  markdown: string
): Promise<{ contentHash: string; byteSize: number }> {
  const body = new TextEncoder().encode(markdown)
  const contentHash = await sha256Hex(body)
  await env.DOCS_BUCKET.put(sourceMarkdownKey(docId), body, {
    httpMetadata: { contentType: MARKDOWN_CONTENT_TYPE },
    customMetadata: { contentHash }
  })
  return { contentHash, byteSize: body.byteLength }
}

export async function readSourceMarkdown(env: Env, docId: string): Promise<string | null> {
  const obj = await env.DOCS_BUCKET.get(sourceMarkdownKey(docId))
  if (!obj) return null
  return obj.text()
}

function yjsSnapshotKey(docId: string): string {
  return `docs/${docId}/yjs/snapshot.bin`
}

/**
 * Yjs binary snapshot helpers. These persist `Y.encodeStateAsUpdate(doc)`
 * bytes so a `DocRoomDO` cold-wake can rebuild the live collab state
 * without round-tripping through BlockNote JSON. There's only ever one
 * current Y.Doc snapshot per doc — the human-facing revision history
 * stays in the JSON layout above.
 */
export async function readYjsSnapshot(env: Env, docId: string): Promise<Uint8Array | null> {
  const obj = await env.DOCS_BUCKET.get(yjsSnapshotKey(docId))
  if (!obj) return null
  return new Uint8Array(await obj.arrayBuffer())
}

export async function writeYjsSnapshot(env: Env, docId: string, bytes: Uint8Array): Promise<void> {
  await env.DOCS_BUCKET.put(yjsSnapshotKey(docId), bytes, {
    httpMetadata: { contentType: YJS_CONTENT_TYPE }
  })
}

const MESSAGE_QUERY_AWARENESS = 3

// Sentinel origin for the R2 → Y.Doc rehydrate. The update observer
// checks this so initial load doesn't re-broadcast or schedule a
// duplicate write of the bytes we just read.
const LOAD_ORIGIN = Symbol('doc-room-do.load')

interface SocketAttachment {
  userId: string
  canEdit: boolean
}

export class DocRoomDO extends DurableObject<Env> {
  private doc: Y.Doc | null = null
  private awareness: awarenessProtocol.Awareness | null = null
  private docId: string | null = null
  private loadPromise: Promise<void> | null = null

  // R2 snapshot coalescing: at most one write inflight; latest pending
  // bytes win when the current write completes.
  private writeInFlight: Promise<void> | null = null
  private writePending: Uint8Array | null = null

  // Materialised-snapshot (snapshot.json) reconciliation. The DO is the
  // authority that keeps the blocks snapshot — what MCP get_doc /
  // search / GET /content read — in step with the live Y.Doc, instead
  // of trusting the best-effort client REST autosave. We skip the write
  // when the rendered content hasn't changed.
  private lastMaterialisedHash: string | null = null
  private materialisedHashLoaded = false

  // B2 (2026-08 review): the DO owns "current content", so a
  // materialised write also flips the git local-edits flag eagerly
  // (the cron-sync clobber guard) once per DO lifetime; the alarm
  // re-flags on every fire to cover a mid-session sync reset.
  private gitFlaggedSinceLoad = false

  // Lock-state cache so we don't D1-read on every Yjs frame. The
  // upgrade handler already tags new sockets read-only when the doc
  // is locked, but a peer that connected pre-lock would otherwise
  // keep writing through their stale `canEdit:true` attachment until
  // they reconnect. The cache catches that case with a small TTL.
  private lockCacheUntil = 0
  private isLockedCached = false

  override async fetch(req: Request): Promise<Response> {
    if (req.headers.get('upgrade') !== 'websocket') {
      return new Response('expected websocket upgrade', { status: 426 })
    }
    const url = new URL(req.url)
    const docId = url.searchParams.get('docId')
    if (!docId) return new Response('missing docId', { status: 400 })
    const userId = req.headers.get('x-ctx-user-id') ?? ''
    const canEdit = req.headers.get('x-ctx-can-edit') === '1'
    if (!userId) return new Response('missing user', { status: 401 })

    await this.ctx.storage.put('docId', docId)
    this.docId = docId

    const pair = new WebSocketPair()
    const [client, server] = [pair[0], pair[1]]
    server.serializeAttachment({ userId, canEdit } satisfies SocketAttachment)
    this.ctx.acceptWebSocket(server)

    return new Response(null, { status: 101, webSocket: client })
  }

  override async webSocketMessage(ws: WebSocket, data: ArrayBuffer | string): Promise<void> {
    if (typeof data === 'string') return // y-websocket is binary only
    await this.ensureLoaded()
    const buf = new Uint8Array(data)
    const decoder = decoding.createDecoder(buf)
    const messageType = decoding.readVarUint(decoder)
    const attachment = (ws.deserializeAttachment() ?? {}) as Partial<SocketAttachment>
    const canEdit = attachment.canEdit === true

    switch (messageType) {
      case MESSAGE_SYNC: {
        const peekDecoder = decoding.clone(decoder)
        const syncSubType = decoding.readVarUint(peekDecoder)
        const isWrite =
          syncSubType === sync.messageYjsSyncStep2 || syncSubType === sync.messageYjsUpdate
        if (isWrite && !canEdit) return // silently drop writes from read-only peers
        if (isWrite && (await this.isLocked())) return // doc was locked while this peer was connected
        const encoder = encoding.createEncoder()
        encoding.writeVarUint(encoder, MESSAGE_SYNC)
        sync.readSyncMessage(decoder, encoder, this.doc!, ws)
        if (encoding.length(encoder) > 1) ws.send(encoding.toUint8Array(encoder))
        return
      }
      case MESSAGE_AWARENESS: {
        awarenessProtocol.applyAwarenessUpdate(
          this.awareness!,
          decoding.readVarUint8Array(decoder),
          ws
        )
        return
      }
      case MESSAGE_QUERY_AWARENESS: {
        const states = this.awareness!.getStates()
        const encoder = encoding.createEncoder()
        encoding.writeVarUint(encoder, MESSAGE_AWARENESS)
        encoding.writeVarUint8Array(
          encoder,
          awarenessProtocol.encodeAwarenessUpdate(this.awareness!, [...states.keys()])
        )
        ws.send(encoding.toUint8Array(encoder))
        return
      }
    }
  }

  override async webSocketClose(ws: WebSocket): Promise<void> {
    await this.handleClose(ws)
  }

  override async webSocketError(ws: WebSocket): Promise<void> {
    await this.handleClose(ws)
  }

  private async handleClose(ws: WebSocket): Promise<void> {
    await this.ensureLoaded()
    // Drop this user's awareness entries that have no surviving sockets
    // owning the same userId. Best effort — peers also remove their
    // own state on `beforeunload`.
    const attachment = (ws.deserializeAttachment() ?? {}) as Partial<SocketAttachment>
    if (this.awareness && attachment.userId) {
      const survivors = this.ctx
        .getWebSockets()
        .filter((s) => s !== ws)

      .map((s) => (s.deserializeAttachment() ?? {}) as Partial<SocketAttachment>)
      .map((a) => a.userId)
    if (!survivors.includes(attachment.userId)) {
      const toDrop: number[] = []
      for (const [clientID, state] of this.awareness.getStates()) {
        const owner = (state as { user?: { id?: string } }).user?.id
        if (owner === attachment.userId) toDrop.push(clientID)
      }
      if (toDrop.length > 0) {
        awarenessProtocol.removeAwarenessStates(this.awareness, toDrop, this)
      }
    }
  }
}

// ----- internals --------------------------------------------------------

/**
 * TTL-cached lock check. Avoids a D1 read per Yjs frame while still
 * propagating a fresh lock within `LOCK_CACHE_TTL_MS`. A peer that
 * was tagged `canEdit: true` at upgrade time will eventually see
 * its writes dropped here once an admin flips the lock.
 */
private async isLocked(): Promise<boolean> {
  const now = Date.now()
  if (now < this.lockCacheUntil) return this.isLockedCached
  if (!this.docId) return false
  try {
    this.isLockedCached = await isDocLocked(this.env, this.docId)
  } catch {
    // On D1 error, prefer "not locked" — better to let writes
    // through than to inadvertently freeze the doc.
    this.isLockedCached = false
  }
  this.lockCacheUntil = now + LOCK_CACHE_TTL_MS
  return this.isLockedCached
}

/**
 * Lazy load on first message after construct (cold start OR after a
 * hibernation wake). Idempotent + concurrent-safe. After load, sends
 * syncStep1 to every still-attached socket so peers re-send any
 * updates that landed in-memory but weren't yet persisted to R2.
 */
private async ensureLoaded(): Promise<void> {
  if (this.doc && this.awareness) return
  this.loadPromise ??= this.doLoad()
  await this.loadPromise
}

private async doLoad(): Promise<void> {
  if (!this.docId) {
    this.docId = (await this.ctx.storage.get<string>('docId')) ?? null
  }
  const doc = new Y.Doc()
  if (this.docId) {
    const snapshot = await readYjsSnapshot(this.env, this.docId)
    if (snapshot && snapshot.byteLength > 0) {
      Y.applyUpdate(doc, snapshot, LOAD_ORIGIN)
    }
  }
  doc.on('update', (update: Uint8Array, origin: unknown) => {
    if (origin === LOAD_ORIGIN) return
    this.scheduleSnapshotWrite()
    const msg = encodeSyncUpdate(update)
    this.broadcast(msg, origin)
  })
  const awareness = new awarenessProtocol.Awareness(doc)
  awareness.setLocalState(null)
  awareness.on(
    'update',
    (
      { added, updated, removed }: { added: number[]; updated: number[]; removed: number[] },
      origin: unknown
    ) => {
      const changed = [...added, ...updated, ...removed]
      const msg = encodeAwarenessFrame(awareness, changed)
      this.broadcast(msg, origin)
    }
  )
  this.doc = doc
  this.awareness = awareness

  // Reconcile the materialised snapshot from the freshly-loaded Y.Doc.
  // Heals docs whose blocks snapshot drifted from the collab state
  // (e.g. a doc edited then locked before the client autosave flushed)
  // the next time anyone opens them. Backgrounded so it can't delay
  // the first message.
  this.ctx.waitUntil(this.materialiseSnapshot())

  // Post-eviction resync: ask each still-attached socket for any
  // updates they applied locally but never made it to R2.
  this.broadcast(encodeSyncStep1(doc), undefined)
}

/**
 * Render the live Y.Doc to BlockNote blocks and write `snapshot.json`
 * when it differs from what's already there. This is the server-side
 * source of truth for the materialised body — the B2 decision from
 * the 2026-08 review: the DO owns "current content", so an actual
 * write here also triggers the reindex + git-divergence side effects
 * (`afterMaterialisedWrite`), making search consistency and the
 * cron-sync clobber guard independent of the tab lifecycle. The
 * client REST autosave stays the trigger for REVISIONS only (a
 * deliberate, user-meaningful act).
 */
private async materialiseSnapshot(): Promise<void> {
  if (!this.doc || !this.docId) return
  let blocks: unknown[]
  try {
    blocks = yDocToBlocks(this.doc)
  } catch (err) {
    console.error('doc-room-do: yjs->blocks decode failed', err)
    return
  }
  const content = { blocks }
  let hash: string
  try {
    hash = await hashContent(content)
  } catch {
    return
  }
  if (!this.materialisedHashLoaded) {
    this.lastMaterialisedHash = await readSnapshotHash(this.env, this.docId).catch(() => null)
    this.materialisedHashLoaded = true
  }
  if (hash === this.lastMaterialisedHash) return
  try {
    await writeMaterializedSnapshot(this.env, this.docId, content)
    this.lastMaterialisedHash = hash
    // Empty renders carry no side effects: the first open of a
    // never-seeded doc (git-imported, client hasn't pushed blocks yet)
    // materialises an empty snapshot, and flagging git divergence for
    // that would freeze inbound sync on a pristine doc. The consumer
    // skips empty bodies anyway.
    if (blocks.length > 0) await this.afterMaterialisedWrite()
  } catch (err) {
    console.error('doc-room-do: materialised snapshot write failed', err)
  }
}

/**
 * Side effects of an actual materialised write (B2): flag git
 * divergence eagerly — it is the guard that stops the hourly cron
 * sync from clobbering an edit whose client autosave never flushed —
 * and schedule the (debounced) reindex alarm. The pending marker
 * lives in DO storage and the alarm survives eviction, so a tab that
 * closes inside the debounce window still gets indexed.
 */
private async afterMaterialisedWrite(): Promise<void> {
  if (!this.docId) return
  if (!this.gitFlaggedSinceLoad) {
    this.gitFlaggedSinceLoad = true
    await markGitDocLocallyEdited(this.env, this.docId).catch((err) =>
      console.error('doc-room-do: git local-edits flag failed', err)
    )
  }
  await this.ctx.storage.put('reindexPending', true)
  if ((await this.ctx.storage.getAlarm()) === null) {
    await this.ctx.storage.setAlarm(Date.now() + REINDEX_DEBOUNCE_MS)
  }
}

/**
 * Debounced reindex for DO-materialised content. `source: 'snapshot'`
 * tells the consumer to read snapshot.json (there is no revision row
 * for a materialised write); the consumer's unchanged-hash check makes
 * redundant fires cheap. On failure the pending marker is restored and
 * the alarm re-armed.
 */
override async alarm(): Promise<void> {
  const docId = this.docId ?? ((await this.ctx.storage.get<string>('docId')) ?? null)
  const pending = await this.ctx.storage.get<boolean>('reindexPending')
  if (!docId || !pending) return
  await this.ctx.storage.delete('reindexPending')
  try {
    // Re-flag on every fire: a write-back/sync may have reset the git
    // state to clean mid-session while edits continued.
    await markGitDocLocallyEdited(this.env, docId)
    await this.env.DOC_REINDEX_QUEUE.send({
      docId,
      revisionId: 'do-materialise',
      source: 'snapshot'
    })
  } catch (err) {
    console.error('doc-room-do: reindex alarm failed; re-arming', err)
    await this.ctx.storage.put('reindexPending', true)
    await this.ctx.storage.setAlarm(Date.now() + REINDEX_DEBOUNCE_MS)
  }
}

private broadcast(msg: Uint8Array, skip: unknown): void {
  for (const ws of this.ctx.getWebSockets()) {
    if (ws === skip) continue
    try {
      ws.send(msg)
    } catch {
      // Socket may be in a closing state.
    }
  }

