// In BackofficeDocumentService.GetDocument()
if (document is IInvoiceDocumentBase invoiceDoc && invoiceDoc.InvoiceLines != null)
{
    data.InvoiceLines = invoiceDoc.InvoiceLines
        .Where(kvp => !kvp.Value.IsTaxLine.ValueBoolean) // Exclude tax lines from UI
        .OrderBy(kvp => kvp.Value.Line.ValueInteger)
        .Select(kvp => new InvoiceLineData
        {
            Id = kvp.Key,
            LineNumber = kvp.Value.Line.ValueInteger,
            Description = kvp.Value.Description.ValueString,
            GlAccountId = kvp.Value.Category.ValueString,
            GlAccountDescription = GetGlAccountDescription(kvp.Value.Category.ValueString),
            TaxCodeId = kvp.Value.TaxCode.ValueString,
            TaxType = kvp.Value.TaxType.ValueInteger,
            TaxPercentage = kvp.Value.TaxPercentage.ValueDecimal,
            Amount = kvp.Value.Amount.ValueDecimal,
            IncludesTax = kvp.Value.IncludesTax.ValueBoolean,
            AmountIncTax = kvp.Value.AmountIncTax.ValueDecimal,
            DeductableVATPercentage = kvp.Value.DeductableVATPercentage.ValueDecimal,
            IsTaxLine = false
        })
        .ToList();
}
