## 7. Phase 2 — Column Visibility Logic

Create a composable to determine which columns are visible based on document type, country, and domain settings:

```ts
// web/src/views/domain/archive/bo-entry/hooks/useInvoiceLineColumns.ts

import { computed, type ComputedRef, type Ref } from "vue";
import { DocumentType } from "@/repositories/backoffice/backoffice.types";

interface InvoiceLineColumnVisibility {
    vatCode: boolean;
    deductibleVatPct: boolean;
    incVat: boolean;
    amountIncVat: boolean;
    delete: boolean;
}

export function useInvoiceLineColumns(
    documentType: Ref<DocumentType> | (() => DocumentType),
    legislationCountry: Ref<string> | (() => string),
    multipleVatCodesEnabled: Ref<boolean> | (() => boolean),
    isViewMode: Ref<boolean> | (() => boolean)
): ComputedRef<InvoiceLineColumnVisibility> {
    const getDocType = typeof documentType === "function" ? documentType : () => documentType.value;
    const getCountry = typeof legislationCountry === "function" ? legislationCountry : () => legislationCountry.value;
    const getMultiVat = typeof multipleVatCodesEnabled === "function" ? multipleVatCodesEnabled : () => multipleVatCodesEnabled.value;
    const getViewMode = typeof isViewMode === "function" ? isViewMode : () => isViewMode.value;

    return computed<InvoiceLineColumnVisibility>(() => {
        const isPurchaseInvoice = [DocumentType.PurchaseInvoice, DocumentType.ExpenseReport]
            .includes(getDocType());
        const isSalesInvoice = getDocType() === DocumentType.SalesInvoicePrescanned;

        return {
            vatCode: isSalesInvoice || (isPurchaseInvoice && getMultiVat()),
            deductibleVatPct: isPurchaseInvoice && getCountry() === "BE",
            incVat: isSalesInvoice,
            amountIncVat: isSalesInvoice,
            delete: !getViewMode(),
        };
    });
}
```

**Unit tests** (`useInvoiceLineColumns.spec.ts`):
- Purchase Invoice NL → `vatCode: false`, `deductibleVatPct: false`
- Purchase Invoice BE with `MultipleVATPurchases` → `vatCode: true`, `deductibleVatPct: true`
- Purchase Invoice BE without `MultipleVATPurchases` → `vatCode: false`, `deductibleVatPct: true`
- Sales Invoice → `vatCode: true`, `incVat: true`, `deductibleVatPct: false`
- Expense Claim → same as Purchase Invoice
- View mode → `delete: false`

